<?php session_start();require __DIR__.'/config.php';if(isset($_GET['logout'])){session_destroy();header('Location:index.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['password'])){if(hash_equals(ADMIN_USERNAME,$_POST['username']??'')&&hash_equals(ADMIN_PASSWORD,$_POST['password']))$_SESSION['admin']=true;else$loginError='Usuario o contraseña incorrectos.';}if(empty($_SESSION['admin'])): ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title>Administrador</title></head><body><main class="order-section" style="min-height:100vh"><div class="order-intro"><p class="eyebrow">GESTIÓN MILKITO</p><h2>Panel de administrador.</h2></div><form class="order-form" method="post" autocomplete="off"><label>Usuario<input name="username" autocomplete="off" required></label><label>Contraseña<input type="password" name="password" autocomplete="new-password" required></label><?php if(isset($loginError)): ?><p style="color:#c94b38"><?=e($loginError)?></p><?php endif; ?><button class="btn btn-coral">Ingresar →</button><p><a href="index.php">← Página principal</a></p></form></main></body></html><?php exit;endif;
if(isset($_POST['delete_order'])){$d=db()->prepare('DELETE FROM orders WHERE id=?');$d->execute([(int)$_POST['delete_order']]);header('Location:admin.php');exit;}if(isset($_POST['status'],$_POST['order_id'])){$u=db()->prepare('UPDATE orders SET status=? WHERE id=?');$u->execute([$_POST['status'],(int)$_POST['order_id']]);header('Location:admin.php');exit;}$orders=db()->query("SELECT o.*,GROUP_CONCAT(CONCAT(oi.quantity,' × ',oi.size_name,' ',f.name) SEPARATOR ', ') detail FROM orders o JOIN order_items oi ON oi.order_id=o.id JOIN flavors f ON f.id=oi.flavor_id GROUP BY o.id ORDER BY o.created_at DESC")->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedidos | Milkito</title><link rel="stylesheet" href="assets/style.css"><style>.admin-wrap{max-width:1250px;margin:auto;padding:45px 5%}.admin-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.table-wrap{overflow:auto;background:#fff;border:1px solid var(--line)}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:14px;border-bottom:1px solid var(--line);white-space:nowrap}th{background:#f6e8d8}.status{border:0;border-radius:20px;padding:7px}.delete-btn{border:0;background:#ffe5e1;color:#a83d31;border-radius:18px;padding:8px 11px;cursor:pointer;font-size:12px}.top-actions{display:flex;gap:10px}.top-actions a{border:1px solid var(--line);padding:10px 14px;border-radius:20px;font-size:13px}</style></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">M</span><span>adoquines <b>milkito</b></span></a><div class="top-actions"><a href="index.php">← Página principal</a><a href="admin.php?logout=1">Cerrar sesión</a></div></header><div class="admin-wrap"><div class="admin-head"><div><p class="eyebrow">CENTRAL DE DELIVERY</p><h1>Pedidos recientes</h1></div><span><?=count($orders)?> pedido(s)</span></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Cliente</th><th>Pedido</th><th>Contacto</th><th>Dirección</th><th>Total</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer_name'])?><br><?=e($o['district'])?></td><td><?=e($o['detail'])?></td><td><?=e($o['phone'])?></td><td><?=e($o['address'])?><br><?=e($o['notes'])?></td><td><?=money((float)$o['total'])?></td><td><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><select class="status" name="status" onchange="this.form.submit()"><option <?=($o['status']=='nuevo'?'selected':'')?>>nuevo</option><option <?=($o['status']=='preparando'?'selected':'')?>>preparando</option><option <?=($o['status']=='en camino'?'selected':'')?>>en camino</option><option <?=($o['status']=='entregado'?'selected':'')?>>entregado</option><option <?=($o['status']=='cancelado'?'selected':'')?>>cancelado</option></select></form></td><td><form method="post" onsubmit="return confirm('¿Borrar este pedido definitivamente?')"><input type="hidden" name="delete_order" value="<?=$o['id']?>"><button class="delete-btn" type="submit">🗑 Borrar</button></form></td></tr><?php endforeach;if(!$orders):?><tr><td colspan="8">Aún no hay pedidos.</td></tr><?php endif;?></tbody></table></div></div></body></html>
